#!/usr/bin/env node
/*
 * Builds data/default-data.js from the three source workbooks, using the same
 * importer the website uses. The generated file is what the site shows before
 * anyone imports new Excel files in the browser.
 *
 *   npm install xlsx@0.18.5 jszip@3        (once)
 *   node tools/build-default-data.js "PBI Weekly Report.xlsx" "EPBU ... .xlsx" "Contract details.xlsx"
 */
const fs = require("fs");
const path = require("path");
const XLSX = require("xlsx");
const JSZip = require("jszip");
const { parseWorkbook } = require("../assets/js/importer.js");

(async () => {
  const files = process.argv.slice(2);
  if (!files.length) {
    console.error("Usage: node tools/build-default-data.js <xlsx> [<xlsx> ...]");
    process.exit(1);
  }
  const dataset = { version: 1, builtAt: new Date().toISOString(), tables: {}, sources: {} };
  for (const f of files) {
    const buf = fs.readFileSync(f);
    const res = await parseWorkbook(buf, XLSX, JSZip);
    Object.assign(dataset.tables, res.tables);
    dataset.sources[res.source] = {
      fileName: path.basename(f), importedAt: dataset.builtAt, report: res.report
    };
    console.log(`\n${path.basename(f)} → ${res.label}`);
    res.report.forEach(r => console.log(`  ${r.status.padEnd(7)} ${r.table.padEnd(38)} ${String(r.rows).padStart(5)} rows` +
      (r.missing.length ? `  missing: ${r.missing.join(", ")}` : "")));
  }
  const out = path.join(__dirname, "..", "data", "default-data.js");
  fs.writeFileSync(out, "/* Generated by tools/build-default-data.js — do not edit by hand. */\n" +
    "window.SAR_DEFAULT_DATA = " + JSON.stringify(dataset) + ";\n");
  console.log(`\nWrote ${out} (${(fs.statSync(out).size / 1024).toFixed(0)} KB)`);
})().catch(e => { console.error(e); process.exit(1); });
